use super::*;
use std::{path::Path,sync::Arc};
struct Source;impl dm_preprocess::SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Ok("var/const/global_base=1+2\n/datum/source_probe\n    var/value=7\n    var/list/items[2+1]\n/datum/source_probe/proc/read_value()\n    var/static/cache=make_value()\n    return value+cache\n/proc/make_value()\n    return global_base\n".into())}}
struct Values;impl crate::class_projection::TypeValuePolicy for Values{fn tag(&self,path:dm_ir::SymbolId)->Result<u8,crate::class_projection::ProjectionError>{if path==dm_ir::SymbolId::of("/datum/source_probe"){Ok(32)}else{Err(crate::class_projection::ProjectionError::Unsupported("source fixture has no custom type defaults".into()))}}}
fn prepare_run(front:&dm_tree::frontend::FrontendRevision,host:&impl Resolver,engine:&crate::engine::EngineSnapshot,executor:&dm_exec::BuildExecutor,memo:Option<&crate::lowering_memo::ProcedureMemo>,original:bool,retained:Option<crate::retained_output::RetainedOutput<'_>>)->Result<Prepared,ColdError>{
 let bytes=include_bytes!("../../../../fixtures/native_template.bin");let links=crate::engine_link::capture(bytes,engine).unwrap();let order=crate::type_creation_order::collect(&front.allocation_ledger,&front.expanded.text,front.snapshot.tree.symbols(),&links.inventory).unwrap();let evaluator=crate::driver_facts::DriverEvaluator{pure_calls:None,resource_search_context:None,resolver:host,symbols:front.snapshot.tree.symbols()};
 let links=CapturedLinkInputs{engine_bytes:bytes,engine,references:&links.references,inventory:links.inventory};let declarations=CapturedDeclarationInputs{initializers:&evaluator,type_values:&Values,resource_search_context:None,source_type_order:&order,source_allocation_roster:None};
 if original{prepare_original_captured_classified_with_pinned_abi_memo_revision(front,host,links,declarations,LoweringConfig{workers:1,..Default::default()},Vec::new(),None,None,memo,Some(front),executor,retained)}else{prepare_captured_classified_with_pinned_abi_memo_revision(front,host,links,declarations,LoweringConfig{workers:1,..Default::default()},Vec::new(),None,None,memo,Some(front),executor,retained)}
}
fn run(front:&dm_tree::frontend::FrontendRevision,host:&impl Resolver,engine:&crate::engine::EngineSnapshot,executor:&dm_exec::BuildExecutor,memo:Option<&crate::lowering_memo::ProcedureMemo>,original:bool)->Result<ColdOutput,ColdError>{prepare_run(front,host,engine,executor,memo,original,None)?.into_full()?.compose_borrowed(include_bytes!("../../../../fixtures/native_template.bin"),front,&Values,None,executor,None)}

#[test]fn actual_source_cold_pipeline_preserves_words_and_warm_initializer_stage_without_owned_scalar_parse(){
 let bytes=include_bytes!("../../../../fixtures/native_template.bin");let engine=crate::engine::EngineSnapshot::from_bytes(bytes,1).unwrap().with_bootstrap_catalog().unwrap();let seed=engine.frontend_seed();let db=Arc::new(crate::query_db::QueryDb::default());let provider=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let front=dm_tree::frontend::build_with_executor_and_semantic_state_for_policy_checked(Path::new("source-cold.dme"),&Source,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None},None,&executor,None,true,&provider).unwrap();let front=dm_tree::frontend::FrontendRevision::new(front);
 let mut symbols=dm_ir::SymbolTable::overlay(front.snapshot.tree.shared_symbols());let constants=crate::engine_host::ConstantCatalog::native_516_1687(&mut symbols).unwrap();let runtime=crate::engine_host::RuntimeAliasCatalog::new(engine.identity(),&symbols,Vec::new(),front.snapshot.tree.types().iter().map(|node|node.path).collect(),crate::engine_host::Completeness::Partial).unwrap();let host=crate::engine_host::EngineResolverHost::new(Arc::clone(&front.snapshot.tree),constants,runtime).with_pinned_callables(&engine,&front).unwrap();
 let old=run(&front,&host,&engine,&executor,None,false).unwrap();let stages=crate::stage_reuse::StageProducts::default();let mut cold_memo=crate::lowering_memo::ProcedureMemo::new(77);cold_memo.answers=Some(Arc::clone(&db));cold_memo.startup=Some(Arc::new(crate::startup::StartupArtifacts::default()));cold_memo.stages=Some(stages.for_request(true));
 let before_here=crate::driver_facts::original_scalar_text_parse_count_for_test();let before=executor.install(crate::driver_facts::original_scalar_text_parse_count_for_test);let mut prepared=prepare_run(&front,&host,&engine,&executor,Some(&cold_memo),true,None).unwrap().into_full().unwrap();let(records,warnings)=prepared.take_patch_records().unwrap();let generation_owner=crate::composition::RetainedGeneration::default();let generation=generation_owner.for_request(true);let current=prepared.seal(&front,Arc::from(bytes.as_slice()),Arc::new(Values),None).unwrap().compose_with_generation(&executor,None,Some(&generation)).unwrap();let shape=Arc::new(crate::retained_output::SourceShape::capture(&front,&executor));let inputs=crate::input_snapshot::InputSnapshot::new(0);let archive=crate::publish::ResourceIdentity{bytes:0,hash:0};let base=crate::retained_output::OutputBase::of_full_build(Arc::clone(&shape),records,inputs.clone(),archive,warnings,db.answers_version(),db.answers_context(),Some(db.mark_published()),db.answer_facts(),current.dmb.content_hash()).unwrap();assert!(generation.install_patch_base(base));assert!(generation.publish_successful());assert_eq!(current.dmb.bytes(),old.dmb.bytes());assert!(!cold_memo.initializer_stage_carried.load(std::sync::atomic::Ordering::Acquire));assert!(cold_memo.stages.as_ref().unwrap().publish_successful(db.answers_version()));
 let mut warm_memo=crate::lowering_memo::ProcedureMemo::new(77);warm_memo.answers=Some(Arc::clone(&db));warm_memo.startup=cold_memo.startup.clone();warm_memo.stages=Some(stages.for_request(true));let warm=run(&front,&host,&engine,&executor,Some(&warm_memo),true).unwrap();assert_eq!(warm.dmb.bytes(),current.dmb.bytes());assert!(warm_memo.initializer_stage_carried.load(std::sync::atomic::Ordering::Acquire),"actual original proof preserves existing whole initializer stage hit");assert_eq!(executor.install(crate::driver_facts::original_scalar_text_parse_count_for_test),before,"source runtime/ABI helpers cannot enter owned scalar rendering parser on executor");assert_eq!(crate::driver_facts::original_scalar_text_parse_count_for_test(),before_here,"serial source classification cannot enter owned scalar rendering parser on coordinator");
 let next_generation=generation_owner.for_request(true);let retained=crate::retained_output::RetainedOutput{generation:&next_generation,shape:&shape,inputs,archive};let mut incremental_memo=crate::lowering_memo::ProcedureMemo::new(77);incremental_memo.answers=Some(Arc::clone(&db));incremental_memo.startup=cold_memo.startup.clone();incremental_memo.stages=Some(stages.for_request(true));let prepared=prepare_run(&front,&host,&engine,&executor,Some(&incremental_memo),true,Some(retained)).unwrap();let Prepared::Incremental(patched)=prepared else{panic!("source admission must preserve actual retained output success")};assert_eq!(patched.dmb.bytes(),current.dmb.bytes());assert!(incremental_memo.initializer_stage_carried.load(std::sync::atomic::Ordering::Acquire));
 let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),std::time::Instant::now()+std::time::Duration::from_secs(300));token.cancel();let error=run(&front,&host,&engine,&executor,Some(&warm_memo),true).err().expect("cancelled live source cold pipeline");assert!(matches!(error,ColdError::Operational(ref actual)if actual.kind()==std::io::ErrorKind::Interrupted));drop(binding);assert!(run(&front,&host,&engine,&executor,Some(&warm_memo),true).is_ok());
}

#[test]
fn actual_source_cold_invalid_original_rhs_preserves_complete_legacy_source_diagnostic(){
 struct Invalid;impl dm_preprocess::SourceProvider for Invalid{fn read(&self,_:&Path)->Result<String,String>{Ok("/datum/source_probe\n    var/const/value=1+\n/proc/read_value()\n    return 1\n".into())}}
 let bytes=include_bytes!("../../../../fixtures/native_template.bin");let engine=crate::engine::EngineSnapshot::from_bytes(bytes,1).unwrap().with_bootstrap_catalog().unwrap();let seed=engine.frontend_seed();let db=Arc::new(crate::query_db::QueryDb::default());let provider=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();
 let front=dm_tree::frontend::build_with_executor_and_semantic_state_for_policy_checked(Path::new("source-invalid-cold.dme"),&Invalid,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None},None,&executor,None,true,&provider).unwrap();let front=dm_tree::frontend::FrontendRevision::new(front);
 let mut symbols=dm_ir::SymbolTable::overlay(front.snapshot.tree.shared_symbols());let constants=crate::engine_host::ConstantCatalog::native_516_1687(&mut symbols).unwrap();let runtime=crate::engine_host::RuntimeAliasCatalog::new(engine.identity(),&symbols,Vec::new(),front.snapshot.tree.types().iter().map(|node|node.path).collect(),crate::engine_host::Completeness::Partial).unwrap();let host=crate::engine_host::EngineResolverHost::new(Arc::clone(&front.snapshot.tree),constants,runtime).with_pinned_callables(&engine,&front).unwrap();
 let legacy=run(&front,&host,&engine,&executor,None,false).err().expect("actual old malformed RHS rejects publication");let original=run(&front,&host,&engine,&executor,None,true).err().expect("same cached original syntax rejection rejects publication");assert!(matches!(&legacy,ColdError::Lowering(_)),"legacy source diagnostic remains the comparison authority: {legacy:?}");assert_eq!(format!("{legacy:?}"),format!("{original:?}"),"source kind, authored origin, notes, identity and message must all match");
}
